import re
def parse(path):
    d={}
    for line in open(path, encoding='utf-8'):
        m=re.match(r'\s*"([^"]+)"\s*=\s*"(.*)";\s*$', line)
        if m: d[m.group(1)]=m.group(2)
    return d
en=parse('Hanahuac/en.lproj/Localizable.strings')
def specs(s): return sorted(re.findall(r'%[0-9$]*[@dfsl]+', s))
for lang in ['ko','nah']:
    t=parse(f'Hanahuac/{lang}.lproj/Localizable.strings')
    print(f"=== {lang}: {len(t)} keys translated ===")
    bad=False
    for k,v in t.items():
        if k not in en:
            print(f"  UNKNOWN KEY: {k}"); bad=True; continue
        if specs(v)!=specs(en[k]):
            print(f"  SPEC MISMATCH {k}: en={specs(en[k])} {lang}={specs(v)}"); bad=True
